# Program 6: Dice simulator using the random module
import random


def roll_dice():
    return random.randint(1, 6)


rolls = 0
while True:
    answer = input("Roll the dice? (y/n): ")
    if answer.lower() != "y":
        break
    rolls += 1
    print("You got:", roll_dice())
print("You rolled the dice", rolls, "times. Goodbye!")

# Program 7: Exception handling with try-except-finally

for attempt in range(1, 5):
    print("\nAttempt", attempt)
    try:
        a = int(input("Enter the first number : "))
        b = int(input("Enter the second number: "))
        print("Result =", a / b)
    except ZeroDivisionError:
        print("Error: a number cannot be divided by zero.")
    except ValueError:
        print("Error: please enter whole numbers only.")
    finally:
        print("This line (finally block) always runs.")

# Program 8: try-except-else with IndexError and ValueError

subjects = ["English", "Physics", "Chemistry", "Maths", "Computer Science"]

for i in range(3):
    try:
        pos = int(input("Enter an index (0 to 4): "))
        name = subjects[pos]
    except IndexError:
        print("IndexError: there is no subject at that index.")
    except ValueError:
        print("ValueError: the index must be a number.")
    else:
        print("Subject at index", pos, "is", name)

# Program 10: Count vowels, consonants, uppercase and lowercase letters

vowels = consonants = upper = lower = 0
with open("story.txt", "r") as f:
    text = f.read()

for ch in text:
    if ch.isalpha():
        if ch.lower() in "aeiou":
            vowels += 1
        else:
            consonants += 1
        if ch.isupper():
            upper += 1
        else:
            lower += 1

print("Vowels     :", vowels)
print("Consonants :", consonants)
print("Uppercase  :", upper)
print("Lowercase  :", lower)

# Program 12: Lines starting with 'T' and count of the word "the"

def count_in_file(filename):
    t_lines = 0
    the_count = 0
    with open(filename, "r") as f:
        for line in f:
            if line.startswith("T"):
                t_lines += 1
            for word in line.split():
                if word.strip(".,").lower() == "the":
                    the_count += 1
    return t_lines, the_count


lines, words = count_in_file("story.txt")
print("Lines starting with 'T':", lines)
print('The word "the" occurs', words, "times")

# Program 14: Binary file - search a roll number
import pickle

n = int(input("How many students? "))
with open("students.dat", "wb") as f:
    for i in range(n):
        roll = int(input("Roll number: "))
        name = input("Name       : ")
        pickle.dump([roll, name], f)
print("Records saved in students.dat")


def search(roll_no):
    with open("students.dat", "rb") as f:
        try:
            while True:
                record = pickle.load(f)
                if record[0] == roll_no:
                    return record[1]
        except EOFError:          # end of file reached
            return None


for i in range(2):
    r = int(input("\nEnter roll number to search: "))
    name = search(r)
    if name:
        print("Name of roll number", r, "is", name)
    else:
        print("Roll number", r, "not found")

# Program 16: Append to a binary file and filter records
import pickle

while True:
    code = input("Employee code: ")
    name = input("Name         : ")
    salary = int(input("Salary       : "))
    with open("emp.dat", "ab") as f:          # ab = append in binary mode
        pickle.dump({"code": code, "name": name, "salary": salary}, f)
    if input("Add another? (y/n): ").lower() != "y":
        break

print("\nEmployees earning more than 50000:")
with open("emp.dat", "rb") as f:
    try:
        while True:
            emp = pickle.load(f)
            if emp["salary"] > 50000:
                print(emp["code"], emp["name"], emp["salary"])
    except EOFError:
        pass

# Program 19: Stack using a list

stack = []


def push(item):
    stack.append(item)


def pop():
    if stack == []:
        return "Underflow"           # nothing to remove
    return stack.pop()


def peek():
    if stack == []:
        return "Underflow"
    return stack[-1]


def display():
    if stack == []:
        print("Stack is empty")
    else:
        print("Stack (top first):", *stack[::-1])


while True:
    print("\n1.Push  2.Pop  3.Peek  4.Display  5.Exit")
    ch = int(input("Enter choice: "))
    if ch == 1:
        push(int(input("Enter element: ")))
    elif ch == 2:
        print("Popped:", pop())
    elif ch == 3:
        print("Top element:", peek())
    elif ch == 4:
        display()
    elif ch == 5:
        break
    else:
        print("Invalid choice")

# Program 20: Push even numbers onto a stack, then pop them all

stack = []


def PUSH_EVEN(numbers):
    for n in numbers:
        if n % 2 == 0:
            stack.append(n)


def POP_ALL():
    while stack:
        print(stack.pop(), end=" ")
    print("\nStack Empty")


nums = [12, 7, 34, 9, 18, 5, 40]
